import Link from 'next/link';
import { File, Pencil, Trash2 } from 'lucide-react';

interface MeetingNavigationItemProps {
  title: string;
  href: string;
  active: boolean;
  matchContext?: string;
  onOpen: () => void;
  onEdit?: () => void;
  onDelete?: () => void;
}

/** Navigation and editing are siblings, never nested interactive controls. */
export function MeetingNavigationItem({ title, href, active, matchContext, onOpen, onEdit, onDelete }: MeetingNavigationItemProps) {
  return (
    <div className={`group relative rounded-md border ${active ? 'border-primary/25 bg-primary/10' : matchContext ? 'border-amber-400/30 bg-amber-400/10' : 'border-transparent hover:border-sidebar-border hover:bg-sidebar-hover'}`}>
      <Link href={href} prefetch={false} onClick={onOpen} aria-current={active ? 'page' : undefined}
        className="block rounded-md px-2.5 py-2.5 text-sidebar-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
        <div className={`flex items-start gap-2.5 ${onEdit || onDelete ? 'pr-20' : ''}`}>
          <span className="mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-background/60 text-muted-foreground"><File aria-hidden="true" className="h-4 w-4" /></span>
          <span className="min-w-0 flex-1">
            <span className="line-clamp-2 text-sm font-medium leading-5">{title}</span>
            <span className="mt-1 block text-xs text-muted-foreground">Recent meeting</span>
          </span>
        </div>
        {matchContext && <span className="mt-2 block rounded-md border border-amber-400/30 bg-amber-400/10 p-2 text-xs leading-5 text-amber-800 dark:text-amber-100"><span className="font-medium">Match: </span>{matchContext}</span>}
      </Link>
      {(onEdit || onDelete) && <div className="absolute right-1.5 top-2 flex items-center gap-1 opacity-100 transition-opacity sm:opacity-0 sm:group-hover:opacity-100 sm:group-focus-within:opacity-100 motion-reduce:transition-none">
        {onEdit && <button type="button" onClick={onEdit} aria-label={`Edit meeting title: ${title}`}
          className="flex h-9 w-9 items-center justify-center rounded-md text-muted-foreground hover:bg-sidebar-hover hover:text-sidebar-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"><Pencil aria-hidden="true" className="h-4 w-4" /></button>}
        {onDelete && <button type="button" onClick={onDelete} aria-label={`Delete meeting: ${title}`}
          className="flex h-9 w-9 items-center justify-center rounded-md text-muted-foreground hover:bg-destructive/10 hover:text-destructive focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"><Trash2 aria-hidden="true" className="h-4 w-4" /></button>}
      </div>}
    </div>
  );
}

import { useEffect, useState } from 'react';

/** Shared breakpoint keeps the sidebar, content offset and floating controls aligned. */
export function useCompactLayout(): boolean {
  const [compact, setCompact] = useState(false);
  useEffect(() => {
    const media = window.matchMedia('(max-width: 1023px)');
    const update = () => setCompact(media.matches);
    update();
    media.addEventListener('change', update);
    return () => media.removeEventListener('change', update);
  }, []);
  return compact;
}

/** A single meeting's chat state. Synchronous gates protect double clicks;
 * generation checks prevent stale async completions from replacing newer state.
 * No React setter side effects and no dependency on an installed Tauri runtime.
 */
export interface ChatMessage {
  id: string;
  meeting_id: string;
  role: 'user' | 'assistant';
  content: string;
  created_at: string;
  status?: 'pending' | 'failed';
  context_truncated?: boolean;
}

export type ChatInvoke = <T>(command: string, args: Record<string, unknown>) => Promise<T>;
export interface ChatSnapshot {
  messages: ChatMessage[];
  draft: string;
  loaded: boolean;
  busy: 'loading' | 'sending' | 'clearing' | null;
  error: string | null;
  contextTruncated: boolean;
}

export class MeetingChatSession {
  private snapshot: ChatSnapshot = {
    messages: [], draft: '', loaded: false, busy: null, error: null, contextTruncated: false,
  };
  private listeners = new Set<() => void>();
  private epoch = 0;
  private retry: { id: string; question: string } | null = null;

  constructor(private readonly meetingId: string, private readonly invoke: ChatInvoke) {}

  getSnapshot = (): ChatSnapshot => this.snapshot;
  subscribe = (listener: () => void): (() => void) => {
    this.listeners.add(listener);
    return () => { this.listeners.delete(listener); };
  };
  private update(patch: Partial<ChatSnapshot>): void {
    this.snapshot = { ...this.snapshot, ...patch };
    this.listeners.forEach(listener => listener());
  }
  setDraft = (draft: string): void => { this.update({ draft }); };

  /** Invalidate callbacks on unmount, including a meeting switch. */
  invalidate = (): void => {
    this.epoch++;
    this.update({ loaded: false, busy: null });
  };

  load = async (): Promise<void> => {
    if (this.snapshot.loaded || this.snapshot.busy) return;
    const epoch = ++this.epoch;
    this.update({ busy: 'loading', error: null });
    try {
      const messages = await this.invoke<ChatMessage[]>('api_chat_history', { meetingId: this.meetingId });
      if (epoch !== this.epoch) return;
      // Reject cross-meeting data rather than accidentally displaying it.
      if (messages.some(message => message.meeting_id !== this.meetingId)) throw new Error('Meeting mismatch');
      this.update({ messages, loaded: true, busy: null });
    } catch {
      if (epoch === this.epoch) this.update({ busy: null, error: 'Could not load chat history. Retry before sending a question.' });
    }
  };

  send = async (provider?: string, model?: string): Promise<void> => {
    const question = this.snapshot.draft.trim();
    if (!this.snapshot.loaded || this.snapshot.busy || !question) return;
    if (!provider || !model) {
      this.update({ error: 'Choose a summary model before sending a question.' });
      return;
    }
    const epoch = this.epoch;
    const request = this.retry?.question === question
      ? this.retry
      : { id: `chat-${globalThis.crypto.randomUUID()}`, question };
    this.retry = request;
    const optimistic: ChatMessage = {
      id: request.id, meeting_id: this.meetingId, role: 'user', content: question,
      created_at: new Date().toISOString(), status: 'pending',
    };
    this.update({
      busy: 'sending', draft: '', error: null,
      messages: [...this.snapshot.messages.filter(message => message.id !== request.id), optimistic],
    });
    try {
      const reply = await this.invoke<ChatMessage>('api_chat_send', {
        meetingId: this.meetingId, model: provider, modelName: model,
        question, requestId: request.id,
      });
      if (epoch !== this.epoch) return;
      if (reply.meeting_id !== this.meetingId || reply.role !== 'assistant') throw new Error('Meeting mismatch');
      this.retry = null;
      this.update({
        messages: [
          ...this.snapshot.messages.filter(message => message.id !== reply.id)
            .map(message => message.id === request.id ? { ...message, status: undefined } : message),
          reply,
        ],
        busy: null, contextTruncated: Boolean(reply.context_truncated),
      });
    } catch {
      if (epoch !== this.epoch) return;
      this.update({
        busy: null,
        draft: this.snapshot.draft || question,
        messages: this.snapshot.messages.map(message => message.id === request.id ? { ...message, status: 'failed' } : message),
        error: 'The answer could not be completed. Your question is kept below; send again to retry.',
      });
    }
  };

  clear = async (): Promise<void> => {
    // Clear never races an active send, in the UI or through a stale handler.
    // The native command enforces the same per-meeting exclusion.
    if (!this.snapshot.loaded || this.snapshot.busy) return;
    const epoch = ++this.epoch;
    this.update({ busy: 'clearing', error: null });
    try {
      await this.invoke('api_chat_clear', { meetingId: this.meetingId });
      if (epoch !== this.epoch) return;
      this.retry = null;
      this.update({ messages: [], busy: null, contextTruncated: false });
    } catch {
      if (epoch === this.epoch) this.update({ busy: null, error: 'Could not clear chat. The conversation has been kept; please retry.' });
    }
  };
}

import type { Transcript } from '@/types';

export function compareTranscripts(a: Transcript, b: Transcript): number {
  const timeA = a.chunk_start_time ?? a.audio_start_time ?? 0;
  const timeB = b.chunk_start_time ?? b.audio_start_time ?? 0;
  return timeA - timeB || (a.sequence_id ?? 0) - (b.sequence_id ?? 0);
}

const sameTranscript = (a: Transcript, b: Transcript): boolean =>
  a.text === b.text && a.timestamp === b.timestamp && a.speaker === b.speaker &&
  a.is_partial === b.is_partial && a.confidence === b.confidence &&
  a.chunk_start_time === b.chunk_start_time && a.audio_start_time === b.audio_start_time &&
  a.audio_end_time === b.audio_end_time && a.duration === b.duration &&
  (a.word_timestamps === b.word_timestamps || JSON.stringify(a.word_timestamps) === JSON.stringify(b.word_timestamps));

/** Event-owned index. Call outside React state updaters. Snapshots are never
 * mutated; keep the common ordered append O(batch size) plus one array copy.
 * Late corrections are less frequent and use a full rebuild/sort.
 */
export class OrderedTranscripts {
  private byId = new Map<string, Transcript>();
  private snapshot: Transcript[] = [];
  getSnapshot = (): Transcript[] => this.snapshot;
  private key(item: Transcript): string {
    return item.sequence_id === undefined ? `id:${item.id}` : `sequence:${item.sequence_id}`;
  }
  clear(): Transcript[] {
    this.byId.clear();
    this.snapshot = [];
    return this.snapshot;
  }
  merge(incoming: readonly Transcript[], preserveExisting = false): Transcript[] {
    const additions: Transcript[] = [];
    let replaced = false;
    for (const item of incoming) {
      const key = this.key(item);
      const previous = this.byId.get(key);
      if (previous) {
        // A late partial must never overwrite a final recognition result.
        if (preserveExisting || (!previous.is_partial && item.is_partial) || sameTranscript(previous, item)) continue;
        this.byId.set(key, { ...item, id: previous.id });
        replaced = true;
      } else {
        this.byId.set(key, item);
        additions.push(item);
      }
    }
    if (!replaced && additions.length === 0) return this.snapshot;
    if (replaced) {
      this.snapshot = [...this.byId.values()].sort(compareTranscripts);
    } else {
      additions.sort(compareTranscripts);
      const previousLast = this.snapshot[this.snapshot.length - 1];
      this.snapshot = !previousLast || compareTranscripts(previousLast, additions[0]) <= 0
        ? [...this.snapshot, ...additions]
        : [...this.snapshot, ...additions].sort(compareTranscripts);
    }
    return this.snapshot;
  }
}
